(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20+Math.cos(y*0.013-t*0.18)*14;
  const w1y = Math.cos(y*0.02-t*0.22)*18+Math.sin(x*0.015+t*0.3)*12;
  const wx2 = Math.sin((x+w1x)*0.012+t*0.15)*12+Math.cos((y+w1y)*0.01-t*0.12)*10;
  const wy2 = Math.cos((y+w1y)*0.014-t*0.1)*11+Math.sin((x+w1x)*0.011+t*0.2)*9;
  const sx = x+w1x+wx2, sy = y+w1y+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.9],
    [400+Math.sin(t*0.45+3)*70,140+Math.cos(t*0.65+2)*90,0.11,2.1,0.7],
    [80+Math.cos(t*0.55+1)*110,40+Math.sin(t*0.75+4)*50,0.05,1.8,1.3]
  ];
  let act=0,inh=0,ring=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp)*amp;
    inh+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    ring+=Math.sin(d*0.15-t*sp*1.5)*Math.exp(-d*0.008)*amp*0.5;
  }
  act/=8;inh/=8;ring/=8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6)+Math.cos(sx*0.02+sy*0.06+t*0.9))/4+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8)+Math.cos(dist*0.03+ang*5+t*1.0))*0.25;
  let minD=999,minD2=999;
  for(let i=0;i<8;i++){
    const a=i*0.7854+t*0.15,r=40+Math.sin(t*0.3+i*1.2)*25;
    const d=Math.sqrt((sx-(cx+Math.cos(a)*r))**2+(sy-(cy+Math.sin(a)*r))**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const cell=Math.tanh((minD2-minD)*0.15)*0.4;
  const r1=act-inh*0.7,r2=act*0.5+inh*0.3-ring*0.4;
  const reaction=Math.tanh((r1*0.6+r2*0.4+bg*0.25+spiral+cell)*2.0);
  const tex=(Math.sin(sx*0.8)*Math.sin(sy*0.8)+Math.sin(sx*1.3+t*2)*Math.sin(sy*0.9-t*1.5))*0.05;
  const v=(reaction*0.7+cell*0.2+tex)*0.5+0.5;
  const pal=[[6,12,52],[12,55,95],[18,110,130],[35,170,155],[180,195,65],[215,145,55],[210,95,65],[175,50,70],[100,25,60],[40,12,55],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.3?1.05:0.95;
  const glow=Math.max(0,ring*0.3);
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0)
  ];
}
